  std::lock_guard lock(seg_mtx_);

  if (id_map_ && id_map_->has(doc.pk())) {
    return Status::AlreadyExists("insert failed: doc_id[", doc.pk(),
                                 "] already exists in collection");
  }

  doc.set_operator(Operator::INSERT);

